import numpy as np
import time

def construct():
    start_time = time.time()
    deadline = start_time + 55.0  # Safety margin (60s limit)
    
    N = 17
    MIN_DIST = 6
    NUM_WORDS = 1 << N
    
    # 1. Generate the 256-word linear seed code
    # Quadratic residues mod 17
    Q = {1, 2, 4, 8, 9, 13, 15, 16}
    
    # Generator vector g as an integer
    g = 0
    for q in Q:
        g |= (1 << q)
        
    # Basis: cyclic shifts of g
    # In F2, the code is generated by the circulant matrix.
    # Basis vectors are g, g rotated left by 1, ..., g rotated left by 8.
    # Rotation left by 1: ((g << 1) | (g >> 16)) & 0xFFFFF
    basis = [g]
    for i in range(1, 9):
        # Rotate left by 1
        g = ((g << 1) | (g >> (N - 1))) & (NUM_WORDS - 1)
        basis.append(g)
        
    # Generate all 2^9 linear combinations
    # We need the ones with bit 0 == 0 (shortening)
    seed_words = set()
    for mask in range(512):
        w = 0
        for i in range(9):
            if (mask >> i) & 1:
                w ^= basis[i]
        # Shortening: keep only if bit 0 is 0
        if (w & 1) == 0:
            seed_words.add(w)
            
    seed_list = list(seed_words)
    # Should be 256 words
    
    # 2. Precompute offsets for distance < 6 (i.e., distance 0 to 5)
    # offsets[i] = 1 if popcount(i) <= 5 else 0
    # We only need the list of offsets where popcount <= 5
    offsets = []
    for i in range(NUM_WORDS):
        if i.bit_count() <= 5:
            offsets.append(i)
    offsets = np.array(offsets, dtype=np.uint32)
    
    # 3. Greedy Fill Function
    def greedy_fill(start_words, random_seed):
        valid = np.ones(NUM_WORDS, dtype=bool)
        selected = []
        
        # Add start words
        for w in start_words:
            if valid[w]:
                selected.append(w)
                # Invalidate w and all neighbors with dist < 6
                # Neighbors are w ^ offsets
                valid[w ^ offsets] = False
                
        # Get remaining valid candidates
        candidates = np.where(valid)[0]
        
        # Shuffle candidates with specific seed
        rng = np.random.default_rng(random_seed)
        rng.shuffle(candidates)
        
        # Greedy selection
        for c in candidates:
            if valid[c]:
                selected.append(c)
                valid[c ^ offsets] = False
                
        return selected

    # 4. Local Search / Simulated Annealing
    def local_search(initial_code, time_limit):
        code = list(initial_code)
        code_set = set(code)
        valid = np.ones(NUM_WORDS, dtype=bool)
        
        # Initialize valid mask
        for w in code:
            valid[w ^ offsets] = False
            
        current_size = len(code)
        best_size = current_size
        best_code = code[:]
        
        # Parameters
        T = 1.0  # Temperature
        cooling = 0.995
        min_T = 0.05
        rng = np.random.default_rng(42)
        
        # Precompute list of valid words for random selection
        valid_indices = np.where(valid)[0]
        
        while time.time() < time_limit:
            if T < min_T:
                break
                
            # Try to add a random valid word
            if len(valid_indices) > 0:
                idx = rng.integers(0, len(valid_indices))
                new_word = int(valid_indices[idx])
                
                # Check if it's actually valid (race condition check)
                if valid[new_word]:
                    # Accept: add it
                    code.append(new_word)
                    code_set.add(new_word)
                    valid[new_word ^ offsets] = False
                    valid_indices = np.where(valid)[0]
                    
                    if len(code) > best_size:
                        best_size = len(code)
                        best_code = code[:]
                    
                    # Cooling
                    T *= cooling
                else:
                    # Reject: do nothing, maybe cool down faster
                    T *= cooling**2
            else:
                # No valid words left, try to remove a random word and re-optimize?
                # For now, just stop or restart.
                # Let's try to remove a random word to free up space
                if len(code) > 0:
                    rem_idx = rng.integers(0, len(code))
                    rem_word = code[rem_idx]
                    code.pop(rem_idx)
                    code_set.remove(rem_word)
                    
                    # Re-validate: we can't just set valid[rem_word] = True because
                    # other words might still block its neighbors.
                    # But for a simple heuristic, let's just mark it and its neighbors
                    # as potentially valid? No, that's complex.
                    # Let's just restart the valid array? Too slow.
                    # Let's just break and rely on restarts.
                    break
                
                T *= cooling**5
        
        return best_code

    # 5. Main Loop with Restarts
    best_solution = seed_list[:]
    best_len = len(best_solution)
    
    run_id = 0
    while time.time() < deadline:
        # Run greedy fill starting from seed
        res = greedy_fill(seed_list, run_id)
        
        if len(res) > best_len:
            best_len = len(res)
            best_solution = res[:]
            
        # Occasionally try local search on the best solution found so far
        # Local search is expensive, so do it less frequently
        if run_id % 5 == 0 and time.time() < deadline - 10.0:
            ls_res = local_search(best_solution, time.time() + 5.0)
            if len(ls_res) > best_len:
                best_len = len(ls_res)
                best_solution = ls_res[:]
            
        run_id += 1
        
        # Check time more frequently if run_id is large
        if run_id % 10 == 0:
            if time.time() > deadline:
                break

    return best_solution
